const $=s=>document.querySelector(s), artists=HC.artists;
function art(i,v=0){const noise='<filter id="grain'+i+v+'"><feTurbulence type="fractalNoise" baseFrequency=".8" numOctaves="3" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".14"/></feComponentTransfer></filter>';let shape=i===0?`<rect width="500" height="500" fill="#d4d3c6"/><g transform="rotate(-14 250 250)"><path d="M80 400 180 90 240 310 330 100 395 390" fill="none" stroke="#111" stroke-width="65"/><rect x="50" y="245" width="400" height="45" fill="#c1ff00"/></g><text x="25" y="465" font-family="monospace" font-size="16">NOX / TRACE ${v+1} — MARSEILLE</text>`:i===1?`<rect width="500" height="500" fill="#777"/><path d="M0 500V120L150 40V500M190 500V140L340 80V500M370 500V30L500 0V500" fill="#bbb"/><path d="M150 40v460h40V140M340 80v420h30V30" fill="#222"/>${Array.from({length:20},(_,k)=>`<rect x="${15+(k%4)*115}" y="${130+Math.floor(k/4)*65}" width="30" height="40" fill="#353535"/>`).join('')}<path d="M0 500 500 310V500" fill="#151515"/><circle cx="285" cy="367" r="15" fill="#111"/><path d="M280 380 265 455M289 380l20 70" stroke="#111" stroke-width="18"/>`:`<rect width="500" height="500" fill="#c1ff00"/><path d="m155 100 60-25q35 35 70 0l60 25 80 95-65 50-35-45v225H175V200l-35 45-65-50z" fill="#191a17"/><text x="250" y="250" text-anchor="middle" fill="#c1ff00" font-family="Arial" font-weight="900" font-size="28" transform="rotate(-8 250 250)">HORS</text><text x="250" y="280" text-anchor="middle" fill="#c1ff00" font-family="Arial" font-weight="900" font-size="28" transform="rotate(-8 250 250)">LIMITES.</text>`;return `<div class="visual" role="img" aria-label="Illustration de démonstration : univers de ${artists[i].name}"><svg viewBox="0 0 500 500" xmlns="http://www.w3.org/2000/svg"><defs>${noise}</defs>${shape}<rect width="500" height="500" filter="url(#grain${i}${v})" opacity=".7"/></svg></div>`}
function cards(){return `<div class="artists">${artists.map((a,i)=>`<a class="artcard" href="#/artiste/${a.id}">${art(i)}<div class="meta"><div><h3>${a.name}</h3><span class="label">${a.discipline}</span></div><span>↗</span></div></a>`).join('')}</div>`}
function program(){return HC.program.map(p=>`<div class="row"><span class="time">${p[0]}</span><div><h3>${p[1]}</h3><p>${p[2]}</p></div><span class="label">${p[3]}</span></div>`).join('')}
function head(n,t,p=''){return `<div class="pagehead"><span class="eyebrow">HORS CADRE / ${n}</span><h1>${t}</h1><p>${p}</p></div>`}
function closing(){return `<section class="section closing"><h2>ON SE VOIT<br>HORS CADRE ?</h2><div><a class="btn" href="https://shotgun.live/fr" target="_blank" rel="noopener">Prendre ma place ↗</a><p class="notice">Démo : lien vers l’accueil Shotgun.<br>Aucun billet pour cet événement fictif.</p></div></section>`}
function home(){return `<section class="hero"><div class="eyebrow"><span class="dot">Cultures libres · Marseille</span><span>Art / Musique / Pop-up / Bar</span></div><h1 class="wordmark">HORS CADRE</h1><div class="heroimage"><img src="assets/live.jpg" alt="Foule et faisceaux lumineux en concert, photographie d’ambiance"><div class="badge">ÉDITION<strong>001</strong>MARSEILLE</div><div class="herocopy"><h2>LA VILLE DÉBORDE.<br>NOUS AUSSI.</h2><p>Trois artistes. Des sons qui résonnent.<br>Un lieu brut, des idées libres. Et vous.</p><a class="btn" href="#/concept">Explorer l’événement <span>↗</span></a></div></div><div class="hero-bottom"><span>SAMEDI · DATE À VENIR<br>16:00 — 00:00</span><span>MARSEILLE, LIEU INDUSTRIEL<br>ADRESSE À CONFIRMER</span><a class="textlink" href="#/popup">Trois univers. Un même terrain de jeu. ↗</a></div></section><div class="ticker"><span>ART SANS FRONTIÈRES</span><span>✳</span><span>SONS SANS ÉTIQUETTES</span><span>✳</span><span>MARSEILLE SANS FILTRE</span></div><section class="section intro"><span class="label">01 / LE MANIFESTE</span><div><h2>Sortir des lignes.<br>Faire place aux rencontres.</h2><p>HORS CADRE investit un bâtiment industriel marseillais le temps d’une journée et d’une nuit. L’art s’expose, les basses circulent, les créations changent de mains. Un rendez-vous indépendant pour celles et ceux qui font bouger la ville.</p><a class="textlink" href="#/concept">Lire le manifeste ↗</a></div></section><section class="section"><div class="section-head"><h2>Trois artistes. Zéro cadre.</h2><a href="#/popup" class="textlink">ENTRER DANS LE POP-UP ↗</a></div>${cards()}</section><section class="section night"><div class="section-head"><h2>Du jour jusqu’à la nuit.</h2><span class="label">16:00 → 00:00</span></div>${program()}<p class="notice">Programmation fictive pour la démonstration.</p></section>${closing()}`}
function concept(){return head('01 / LE CONCEPT','LA CULTURE<br>EN MOUVEMENT.','Un événement indépendant. Quatre univers qui se croisent. Une autre façon de vivre Marseille.')+`<section class="section intro"><span class="label">LE MANIFESTE</span><div><h2>Pas de frontières<br>entre les disciplines.</h2><p>Nous croyons aux rencontres qui ne sont pas prévues. À une photographie découverte entre deux morceaux. À une conversation au bar qui devient une collaboration. HORS CADRE donne un terrain commun aux artistes émergents et aux publics curieux.</p><p>Le lieu : un bâtiment industriel réinvesti à Marseille, choisi pour son caractère brut. Le lieu définitif et les informations d’accès seront annoncés avant toute ouverture réelle de billetterie.</p></div></section><section class="section info-grid">${[['01 / ART','Des murs aux regards','Sérigraphie, photographie et installations : trois façons de raconter le territoire.'],['02 / MUSIQUE','Les sons de la ville','Hip-hop, rap, neo-soul et bass music. Une progression du warm-up au dernier set.'],['03 / POP-UP','De l’artiste à vous','Petites éditions, textiles et objets indépendants. Découvrez les histoires derrière les créations.'],['04 / BAR','Le point de rencontre','Un espace pour se retrouver et prendre le temps. Boissons avec et sans alcool au programme.']].map(x=>`<article><span class="label">${x[0]}</span><h2>${x[1]}</h2><p>${x[2]}</p></article>`).join('')}</section><section class="section night"><div class="section-head"><h2>Le programme / 001</h2><span class="label">SAMEDI · DATE À VENIR</span></div>${program()}<p class="notice">Artistes musicaux fictifs. Fin de l’événement à minuit.</p></section>${closing()}`}
function products(a,i){return `<section class="section"><div class="section-head"><h2>Les créations.</h2><span class="label">${a.products.length} PIÈCES / DÉMO</span></div><div class="products">${a.products.map((p,j)=>`<article class="product">${art(i,j+1)}<h3>${p.name}</h3><p>${p.desc}</p><span class="label">${p.stock?'Disponible · collection fictive':'Épuisé'}</span><button class="buy" data-buy="${i},${j}" ${p.stock?'':'disabled'}><span>${p.stock?'Acheter ↗':'Indisponible'}</span><span>${p.price} €</span></button></article>`).join('')}</div><p class="notice">Visuels illustratifs · Catalogue fictif · Aucun paiement ni commande réelle.</p></section>`}
function bio(a,i,full=false){return `<section class="section artist-intro">${art(i)}<div><span class="label">${a.discipline} / Marseille</span><h2>${a.name}</h2><p>${a.bio}</p><p class="notice">Visuel illustratif et texte de présentation provisoire. Aucune validation officielle des exposants.</p>${full?`<a class="textlink" href="#/popup">← Retour au pop-up</a>`:`<a class="textlink" href="#/artiste/${a.id}">Découvrir l’artiste et sa collection ↗</a>`}</div></section>${products(a,i)}`}
let selected=0,edition=0;
function popup(){return head('02 / LE POP-UP','L’ART À EMPORTER.','Des petites séries, des grandes idées. Découvrez les trois exposants de l’édition 001 et leurs collections.')+`<div class="tabs" role="tablist" aria-label="Artistes">${artists.map((a,i)=>`<button role="tab" id="artist-tab-${i}" aria-controls="artist-panel" aria-selected="${selected===i}" tabindex="${selected===i?0:-1}" data-artist="${i}">${a.name}</button>`).join('')}</div><div id="artist-panel" role="tabpanel" aria-labelledby="artist-tab-${selected}">${bio(artists[selected],selected)}</div>`}
const archiveShots=[
  ['IMG_1697.webp','Ambiance au bar, lumières rouge et bleue'],
  ['IMG_6795.webp','Portrait au comptoir'],
  ['IMG_7123.webp','Portraits dans la lumière rose'],
  ['IMG_6908.webp','Un DJ aux platines'],
  ['IMG_6935.webp','Gros plan sur une table de mixage'],
  ['IMG_6941.webp','Trois personnes dans une rue de nuit'],
  ['IMG_7241.webp','Deux personnes pendant une soirée'],
  ['IMG_7200.webp','La cabine DJ'],
  ['IMG_7248.webp','Rencontre entre deux personnes'],
  ['IMG_7286.webp','Les platines sous la lumière rouge']
];
function archiveImage(i,extra=''){
 const p=archiveShots[i];
 return '<button type="button" class="zine-photo '+extra+'" data-photo="'+i+'" aria-label="Agrandir : '+p[1]+'"><img loading="lazy" src="assets/archives/'+p[0]+'" alt="'+p[1]+'" onerror="this.onerror=null;this.src=&quot;assets/live.jpg&quot;"><span class="zine-photo-num">'+String(i+1).padStart(2,'0')+' / 10</span></button>';
}
function archives(){
 const intro=head('03 / LES ARCHIVES','ÇA LAISSE<br>DES TRACES.','Des photographies mises en page comme un magazine : doubles pages, grands formats et notes de nuit.');
 const tabs='<div class="tabs" role="tablist" aria-label="Archives"><button role="tab" aria-selected="'+(edition===0)+'" data-edition="0">Photo journal / Démo</button><button role="tab" aria-selected="'+(edition===1)+'" data-edition="1">Édition 001 · À venir</button></div>';
 if(edition===1)return intro+tabs+'<section class="section"><div class="empty"><span class="label">HORS CADRE / ÉDITION 001</span><h2>Archives à venir.</h2><p>La première édition HORS CADRE est un projet fictif. Ses archives officielles pourront être intégrées après un événement réel.</p><button class="btn" data-edition="0">Feuilleter le photo journal ↗</button></div></section>';
 return intro+tabs+
 '<section class="zine-archive" aria-label="Photo journal photographique">'+
 '<div class="zine-heading"><span>HORS CADRE / PHOTO JOURNAL</span><span>MARSEILLE / 10 IMAGES</span></div>'+
 '<div class="zine-book zine-cover">'+archiveImage(0,'zine-cover-shot')+'<div class="zine-gutter" aria-hidden="true"></div><div class="zine-hand-title">HORS<br>CADRE</div><div class="zine-page-no">PHOTO JOURNAL / VOLUME 000</div></div>'+
 '<div class="zine-book zine-spread">'+archiveImage(1,'zine-page')+archiveImage(2,'zine-page')+'<div class="zine-liner-notes"><strong>NOTES DE NUIT / 01</strong><p>Des visages, des couleurs et des fragments de vie nocturne : un journal photographique conçu comme un livret à feuilleter.</p><small>MARSEILLE / RENCONTRES / CULTURE</small></div><div class="zine-gutter" aria-hidden="true"></div></div>'+
 '<div class="zine-book zine-spread">'+archiveImage(3,'zine-page')+archiveImage(4,'zine-page')+'<div class="zine-corner-label">SIDE A — SOUND SYSTEM</div><div class="zine-gutter" aria-hidden="true"></div></div>'+
 '<div class="zine-book zine-spread">'+archiveImage(5,'zine-page')+archiveImage(6,'zine-page')+'<div class="zine-corner-label">SIDE B — PEOPLE & PLACES</div><div class="zine-gutter" aria-hidden="true"></div></div>'+
 '<div class="zine-book zine-spread"><div class="zine-double-cell">'+archiveImage(7,'zine-page')+archiveImage(8,'zine-page')+'</div>'+archiveImage(9,'zine-page')+'<div class="zine-gutter" aria-hidden="true"></div><div class="zine-corner-label">AFTER HOURS — FIN.</div></div>'+
 '<div class="zine-end"><span>HORS CADRE / À SUIVRE.</span><span>PHOTO JOURNAL — 000</span></div>'+
 '<p class="notice">Sélection photographique fournie pour la maquette. Ces images ne sont pas présentées comme les archives d’une édition réelle de HORS CADRE. Crédits et droits de diffusion à confirmer avant publication publique.</p>'+
 '</section>';
}
function infos(){return head('04 / INFOS PRATIQUES','ON SE RETROUVE OÙ ?','Les premières informations de l’édition 001. Ce projet est fictif : aucune réservation n’est ouverte.')+`<section class="section info-grid">${[['Date & horaires','Un samedi, date à confirmer.<br>Ouverture à 16 h. Fin à minuit.'],['Lieu & accès','Bâtiment industriel réinvesti à Marseille.<br>Adresse, transports et accès vélo à venir.'],['Billets & entrée','Tarif de travail : 18 € (hypothèse pédagogique).<br>Le bouton Billetterie mène à l’accueil Shotgun. Aucun billet HORS CADRE n’est en vente.'],['Accessibilité','Les conditions d’accès PMR, les sanitaires et les aménagements seront précisés une fois le lieu validé.'],['Sur place','Exposition, pop-up, musique et espace bar.<br>Une sélection de boissons sans alcool est prévue.'],['Contact & réseaux','Coordonnées et comptes officiels à venir.<br>Aucun contact ni compte d’artiste fictif n’est présenté comme réel.']].map(x=>`<article><h2>${x[0]}</h2><p>${x[1]}</p></article>`).join('')}</section>`}
function legal(){return head('INFORMATIONS','LE CADRE<br>DE LA DÉMO.')+`<section class="section legal"><h2>Projet fictif</h2><p>HORS CADRE est un prototype pédagogique. Les noms des trois exposants sont fournis pour ce projet. Leurs biographies, créations, illustrations et tarifs sont provisoires et ne constituent pas un catalogue officiel. Le lieu, la date et la commercialisation ne sont pas confirmés.</p><h2>Achats & billetterie</h2><p>Les boutons d’achat ouvrent une simulation sans paiement, sans commande et sans collecte de coordonnées. Le lien Shotgun ouvre l’accueil de la plateforme externe, dont les propres conditions s’appliquent.</p><h2>Données personnelles</h2><p>Ce prototype n’intègre aucun formulaire, traceur publicitaire ou outil d’analyse. Aucun compte utilisateur n’est créé et aucune donnée bancaire n’est demandée.</p><h2>Crédits visuels</h2><p>Photographie d’ambiance : <a class="textlink" href="https://images.unsplash.com/photo-1470229722913-7c0e2dbbafd3" target="_blank" rel="noopener">source photographique Unsplash ↗</a>. Les compositions graphiques et les représentations de produits sont des illustrations créées pour cette démonstration. Les archives 000 utilisent des cadrages de la même photo.</p><h2>Avant une exploitation réelle</h2><p>Les mentions d’éditeur, l’identité du vendeur, les crédits photographiques complets, les conditions de vente, la politique de confidentialité et les modalités de billetterie devront être complétés et validés.</p></section>`}
function render(focus=false){let path=location.hash.slice(1)||'/';let html;if(path==='/')html=home();else if(path==='/concept')html=concept();else if(path==='/popup')html=popup();else if(path==='/archives')html=archives();else if(path==='/infos')html=infos();else if(path==='/mentions')html=legal();else if(path.startsWith('/artiste/')){let i=artists.findIndex(a=>a.id===path.split('/')[2]);html=i<0?head('404','PAGE INTROUVABLE.'):head('LE POP-UP / '+artists[i].name,'DANS L’UNIVERS<br>DE '+artists[i].name)+bio(artists[i],i,true)}else html=head('404','HORS PISTE.','Cette page n’existe pas.')+'<section class="section"><a class="btn" href="#/">Retour à l’accueil ↗</a></section>';$('#main').innerHTML=html;document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+path));$('nav').classList.remove('open');$('.menu').setAttribute('aria-expanded','false');document.title='HORS CADRE — '+(path==='/'?'Cultures libres, Marseille':path.split('/').pop().toUpperCase());if(focus){window.scrollTo(0,0);$('#main').focus({preventScroll:true})}}
window.addEventListener('hashchange',()=>render(true));$('.menu').onclick=()=>{const open=$('nav').classList.toggle('open');$('.menu').setAttribute('aria-expanded',String(open))};$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});document.addEventListener('click',e=>{let t=e.target.closest('[data-artist],[data-buy],[data-edition],[data-photo]');if(!t)return;if(t.dataset.artist!==undefined){selected=+t.dataset.artist;render();$(`[data-artist="${selected}"]`).focus()}if(t.dataset.edition!==undefined){edition=+t.dataset.edition;render();$(`[data-edition="${edition}"]`).focus()}if(t.dataset.buy){let [i,j]=t.dataset.buy.split(',').map(Number),p=artists[i].products[j];$('#modal-content').innerHTML=`<span class="modal-label">SIMULATION D’ACHAT / ${artists[i].name}</span><h2>${p.name}</h2><p>${p.desc}</p><h3>${p.price} €</h3><p>Cette création fait partie d’un catalogue fictif. Aucun paiement ne sera demandé et aucune commande ne sera enregistrée.</p><button class="btn" id="continue">Continuer la découverte ↗</button>`;$('#modal').showModal();$('#continue').onclick=()=>$('#modal').close()}if(t.dataset.photo!==undefined){const i=Number(t.dataset.photo),p=archiveShots[i];if(p){$('#modal-content').innerHTML='<img src="assets/archives/'+p[0]+'" alt="'+p[1]+'" onerror="this.onerror=null;this.src=&quot;assets/live.jpg&quot;"><p class="notice">Photo journal de démonstration · '+p[1]+'</p>';$('#modal').showModal()}}});document.addEventListener('keydown',e=>{if(e.target.matches('[data-artist]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();selected=e.key==='Home'?0:e.key==='End'?2:(selected+(e.key==='ArrowRight'?1:2))%3;render();$(`[data-artist="${selected}"]`).focus()}});render();

$(".skip").addEventListener("click",e=>{e.preventDefault();$("#main").focus()});
